import json
from itertools import permutations

def build_adjacency(edges):
    adj = {}
    for a, b in edges:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)
    return adj

def compute_assigned_starts(path, base_len):
    starts = {}
    day = 1
    for city in path:
        starts[city] = day
        day += base_len[city]
    return starts

def counted_interval(city, start, assigned_len, is_last):
    end_assigned = start + assigned_len - 1
    # If not last, counted interval includes the departure day (next city's start day)
    end_counted = end_assigned if is_last else end_assigned + 1
    return (start, end_counted)

def covers_interval(interval, target):
    # interval and target are tuples (start, end) inclusive
    return interval[0] <= target[0] and interval[1] >= target[1]

def find_itinerary(cities, desired_stay, edges, total_days, event_requirements):
    # Build adjacency
    adj = build_adjacency(edges)
    # Base assigned lengths for all except the final city (last adds +1 effectively)
    base_len = {c: desired_stay[c] - 1 for c in cities}
    base_sum = sum(base_len.values())  # should be total_days - 1
    assert base_sum == total_days - 1, "Base lengths must sum to total_days - 1"

    # Constraints for exact start days (to prune search efficiently)
    # Edinburgh must start on Day 5 to ensure it's counted across 5-8 with 3 assigned days
    edinburgh_start_exact = event_requirements.get("Edinburgh", None)
    split_start_exact = event_requirements.get("Split", None)

    # We will enforce exact start day for Edinburgh to 5 if present in constraints
    enforce_edinburgh_start = True if edinburgh_start_exact else False
    edinburgh_start_day = edinburgh_start_exact[0] if edinburgh_start_exact else None

    # For Split, we enforce exact start day to the start of the wedding window for determinism
    enforce_split_start = True if split_start_exact else False
    split_start_day = split_start_exact[0] if split_start_exact else None

    # Define a neighbor iteration preference to guide search toward a likely feasible route
    preferred_order = ["Stuttgart", "Edinburgh", "Prague", "Reykjavik", "Vienna", "Manchester", "Split", "Lyon"]
    order_index = {c: i for i, c in enumerate(preferred_order)}

    def next_candidates(last_city, used):
        # Return neighbors not yet used, ordered by preference
        neighbors = [n for n in adj[last_city] if n not in used]
        neighbors.sort(key=lambda x: order_index.get(x, len(preferred_order)))
        return neighbors

    # Try DFS with pruning
    def dfs(path, used):
        # Prune based on adjacency
        if len(path) >= 2:
            if path[-2] not in adj or path[-1] not in adj[path[-2]]:
                return None

        # Compute assigned starts for current partial path
        starts = compute_assigned_starts(path, base_len)

        # Prune: if Edinburgh is in path, enforce its exact start day; if not yet in path, ensure we haven't passed it
        if enforce_edinburgh_start:
            if "Edinburgh" in starts:
                if starts["Edinburgh"] != edinburgh_start_day:
                    return None
            else:
                # Sum of base lengths so far:
                current_sum = sum(base_len[c] for c in path)
                if current_sum > edinburgh_start_day - 1:
                    return None  # we've passed the required start day

        # Prune: if Split is in path, enforce its exact start day; if not, ensure we haven't passed it
        if enforce_split_start:
            if "Split" in starts:
                if starts["Split"] != split_start_day:
                    return None
            else:
                current_sum = sum(base_len[c] for c in path)
                if current_sum > split_start_day - 1:
                    return None  # we've passed the required start day for Split

        # If path complete, validate events and durations
        if len(path) == len(cities):
            # Assign lengths: base for all, but last city gets desired_stay (base + 1)
            last = path[-1]
            assigned_len = {c: base_len[c] for c in path}
            assigned_len[last] = desired_stay[last]

            # Validate total days
            total_assigned = sum(assigned_len[c] for c in path)
            if total_assigned != total_days:
                return None

            # Compute counted intervals and validate durations
            intervals = {}
            for i, city in enumerate(path):
                start = starts[city]
                is_last = (i == len(path) - 1)
                intervals[city] = counted_interval(city, start, assigned_len[city], is_last)
                # Check duration equals desired days
                counted_days = intervals[city][1] - intervals[city][0] + 1
                if counted_days != desired_stay[city]:
                    return None

            # Check event coverage
            # Edinburgh: cover days 5-8
            if "Edinburgh" in event_requirements:
                if not covers_interval(intervals["Edinburgh"], event_requirements["Edinburgh"]):
                    return None
            # Split: cover days 19-23
            if "Split" in event_requirements:
                if not covers_interval(intervals["Split"], event_requirements["Split"]):
                    return None

            # Validate adjacency already checked during build
            return path

        # Extend path
        if not path:
            # Try starting cities ordered by preference
            start_candidates = sorted(cities, key=lambda x: order_index.get(x, len(preferred_order)))
            for c in start_candidates:
                res = dfs([c], {c})
                if res:
                    return res
            return None
        else:
            last = path[-1]
            for nxt in next_candidates(last, used):
                res = dfs(path + [nxt], used | {nxt})
                if res:
                    return res
            return None

    route = dfs([], set())
    if not route:
        raise RuntimeError("No feasible itinerary found given the constraints.")

    # Build final itinerary JSON
    # Compute starts using base lengths, then set assigned lengths (last city gets +1)
    base_starts = compute_assigned_starts(route, base_len)
    assigned_len = {c: base_len[c] for c in route}
    assigned_len[route[-1]] = desired_stay[route[-1]]

    itinerary = []
    for i, city in enumerate(route):
        start = base_starts[city]
        end = start + assigned_len[city] - 1
        itinerary.append({
            "day_range": f"Day {start}-{end}",
            "place": city
        })

    return {"itinerary": itinerary}

def main():
    total_days = 25
    cities = ["Vienna", "Lyon", "Edinburgh", "Reykjavik", "Stuttgart", "Manchester", "Split", "Prague"]

    desired_stay = {
        "Vienna": 4,
        "Lyon": 3,
        "Edinburgh": 4,
        "Reykjavik": 5,
        "Stuttgart": 5,
        "Manchester": 2,
        "Split": 5,
        "Prague": 4
    }

    # Events: inclusive day windows that must be covered by counted presence
    event_requirements = {
        "Edinburgh": (5, 8),
        "Split": (19, 23)
    }

    # Direct flight pairs (undirected)
    edges = [
        ("Reykjavik", "Stuttgart"),
        ("Stuttgart", "Split"),
        ("Stuttgart", "Vienna"),
        ("Prague", "Manchester"),
        ("Edinburgh", "Prague"),
        ("Manchester", "Split"),
        ("Prague", "Vienna"),
        ("Vienna", "Manchester"),
        ("Prague", "Split"),
        ("Vienna", "Lyon"),
        ("Stuttgart", "Edinburgh"),
        ("Split", "Lyon"),
        ("Stuttgart", "Manchester"),
        ("Prague", "Lyon"),
        ("Reykjavik", "Vienna"),
        ("Prague", "Reykjavik"),
        ("Vienna", "Split")
    ]

    result = find_itinerary(cities, desired_stay, edges, total_days, event_requirements)
    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    main()
